local center = vector3(116.0, -744.0, 110.0)
local activateDistance = 260.0
local releaseDistance = 320.0
local spawned = {}
local active = false

local function loadModels()
    local requested = {}
    for _, definition in ipairs(definitions) do
        if not requested[definition.h] then
            requested[definition.h] = true
            RequestModel(definition.h)
        end
    end
    local deadline = GetGameTimer() + 15000
    for hash in pairs(requested) do
        while not HasModelLoaded(hash) and GetGameTimer() < deadline do
            RequestModel(hash)
            Wait(0)
        end
    end
end

local function spawnFib()
    if active then return end
    active = true
    loadModels()
    for index, definition in ipairs(definitions) do
        if HasModelLoaded(definition.h) then
            local object = CreateObjectNoOffset(definition.h, definition.x, definition.y, definition.z, false, false, false)
            if object ~= 0 then
                SetEntityQuaternion(object, definition.qx, definition.qy, definition.qz, definition.qw)
                SetEntityLodDist(object, 1000)
                FreezeEntityPosition(object, true)
                SetEntityCollision(object, true, true)
                spawned[#spawned + 1] = object
            end
        end
        if index % 25 == 0 then Wait(0) end
    end
end

local function removeFib()
    for _, object in ipairs(spawned) do
        if DoesEntityExist(object) then DeleteEntity(object) end
    end
    spawned = {}
    active = false
end

CreateThread(function()
    while true do
        local distance = #(GetEntityCoords(PlayerPedId()) - center)
        if not active and distance <= activateDistance then
            spawnFib()
        elseif active and distance >= releaseDistance then
            removeFib()
        end
        Wait(active and 1000 or 1500)
    end
end)

AddEventHandler('onResourceStop', function(resourceName)
    if resourceName == GetCurrentResourceName() then removeFib() end
end)